/**
 * PRP behandlingsjournal — schema-driven from Meridiq 16412 + 14988 (G4).
 * Registry: journal-prp-schemas.js (generated by buildJournalSchemas.py)
 */
(() => {
  'use strict';

  const MULTI_FIELD_KEYS = new Set();
  const TRISTATE_FIELD_KEYS = new Set();

  function escapeHtml(value) {
    return String(value ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function asArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function chipHtml(label, tone) {
    return `<span class="focus-customer-chip focus-customer-chip--${tone}">${escapeHtml(label)}</span>`;
  }

  function tristateOptions(selected) {
    const current = selected === true ? 'true' : selected === false ? 'false' : '';
    return `
      <option value=""${current === '' ? ' selected' : ''}>—</option>
      <option value="true"${current === 'true' ? ' selected' : ''}>Ja</option>
      <option value="false"${current === 'false' ? ' selected' : ''}>Nej</option>
    `;
  }

  function registerField(field) {
    if (field.type === 'checkboxes') MULTI_FIELD_KEYS.add(field.key);
    if (field.type === 'tristate' || field.type === 'yes_no_textbox') {
      TRISTATE_FIELD_KEYS.add(field.key);
    }
  }

  function renderField(field, fields = {}) {
    const key = field.key;
    const value = fields[key];
    const disabled = field.disabled ? ' disabled' : '';
    const id = `prp-field-${key}`;

    if (field.type === 'yes_no_textbox') {
      const textKey = field.textKey || `${key}Text`;
      return `
        <div class="patient-master-tp-field patient-master-tp-field--split">
          <label class="patient-master-tp-field" for="${id}">
            <span class="patient-master-muted">${escapeHtml(field.label)}</span>
            <select id="${id}" name="${escapeHtml(key)}" data-prp-field="${escapeHtml(key)}" data-prp-tristate="true"${disabled}>
              ${tristateOptions(value)}
            </select>
          </label>
          <label class="patient-master-tp-field" for="${id}-text">
            <span class="patient-master-muted">Kompletterande text</span>
            <input id="${id}-text" type="text" name="${escapeHtml(textKey)}" data-prp-field="${escapeHtml(textKey)}" value="${escapeHtml(fields[textKey] || '')}"${disabled} />
          </label>
        </div>
      `;
    }

    if (field.type === 'tristate') {
      return `
        <label class="patient-master-tp-field" for="${id}">
          <span class="patient-master-muted">${escapeHtml(field.label)}</span>
          <select id="${id}" name="${escapeHtml(key)}" data-prp-field="${escapeHtml(key)}" data-prp-tristate="true"${disabled}>
            ${tristateOptions(value)}
          </select>
        </label>
      `;
    }

    if (field.type === 'select') {
      const options = asArray(field.options)
        .map(
          (option) =>
            `<option value="${escapeHtml(option)}"${String(value || '') === option ? ' selected' : ''}>${escapeHtml(option || '—')}</option>`
        )
        .join('');
      return `
        <label class="patient-master-tp-field" for="${id}">
          <span class="patient-master-muted">${escapeHtml(field.label)}</span>
          <select id="${id}" name="${escapeHtml(key)}" data-prp-field="${escapeHtml(key)}"${disabled}>
            ${options}
          </select>
        </label>
      `;
    }

    if (field.type === 'checkboxes') {
      const selected = new Set(asArray(value).map(String));
      return `
        <fieldset class="patient-master-tp-field patient-master-tp-checkboxes">
          <legend class="patient-master-muted">${escapeHtml(field.label)}</legend>
          ${asArray(field.options)
            .map(
              (option) => `
            <label class="patient-master-tp-checkbox">
              <input type="checkbox" name="${escapeHtml(key)}" value="${escapeHtml(option)}" data-prp-field="${escapeHtml(key)}" data-prp-multi="true"${selected.has(option) ? ' checked' : ''}${disabled} />
              <span>${escapeHtml(option)}</span>
            </label>`
            )
            .join('')}
        </fieldset>
      `;
    }

    if (field.type === 'textarea') {
      return `
        <label class="patient-master-tp-field" for="${id}">
          <span class="patient-master-muted">${escapeHtml(field.label)}</span>
          <textarea id="${id}" name="${escapeHtml(key)}" data-prp-field="${escapeHtml(key)}" rows="3"${disabled}>${escapeHtml(value || '')}</textarea>
        </label>
      `;
    }

    return `
      <label class="patient-master-tp-field" for="${id}">
        <span class="patient-master-muted">${escapeHtml(field.label)}</span>
        <input id="${id}" type="${field.type === 'date' ? 'date' : field.type === 'time' ? 'time' : 'text'}" name="${escapeHtml(key)}" data-prp-field="${escapeHtml(key)}" value="${escapeHtml(value || '')}"${disabled} />
      </label>
    `;
  }

  function render(config, entry, options = {}) {
    const fields = entry?.fields && typeof entry.fields === 'object' ? entry.fields : {};
    const locked = Boolean(options.locked || entry?.locked);
    const entryId = String(entry?.entryId || '');
    const title = String(entry?.title || config.title || 'PRP behandlingsjournal');
    const useMobileSteps = Boolean(options.mobileSteps && !locked);
    const sections = asArray(config.sections);

    function renderSectionBody(section) {
      return section.fields.map((field) => renderField({ ...field, disabled: locked }, fields)).join('');
    }

    let sectionsHtml = '';
    if (useMobileSteps) {
      sectionsHtml = `
        <div class="cco-clinical-mobile-stepper" data-prp-stepper>
          <div class="cco-clinical-mobile-stepper-head">
            <p class="cco-clinical-mobile-stepper-progress" data-prp-step-progress aria-live="polite">
              Steg 1 av ${sections.length}
            </p>
            <p class="cco-clinical-mobile-stepper-title" data-prp-step-title>
              ${escapeHtml(sections[0]?.title || '')}
            </p>
          </div>
          <div class="cco-clinical-mobile-stepper-actions">
            <button type="button" class="customers-utility-button" data-prp-step-prev disabled>
              Föregående
            </button>
            <button type="button" class="customers-utility-button" data-prp-step-next>
              Nästa
            </button>
          </div>
        </div>
        ${sections
          .map(
            (section, index) => `
          <section
            class="patient-master-tp-section cco-clinical-step-panel"
            data-prp-step-panel="${index}"
            data-step-title="${escapeHtml(section.title)}"
            ${index === 0 ? '' : ' hidden'}
          >
            <div class="patient-master-tp-section-body">${renderSectionBody(section)}</div>
          </section>`
          )
          .join('')}
      `;
    } else {
      sectionsHtml = sections
        .map(
          (section) => `
      <details class="patient-master-tp-section" open>
        <summary>${escapeHtml(section.title)}</summary>
        <div class="patient-master-tp-section-body">${renderSectionBody(section)}</div>
      </details>`
        )
        .join('');
    }

    return `
      <article class="focus-customer-data-card patient-master-tp-card${locked ? ' is-locked' : ''}" data-prp-journal-form data-prp-entry-id="${escapeHtml(entryId)}" data-prp-form-variant="${escapeHtml(config.formVariant)}">
        <header class="patient-master-tp-header">
          <div>
            <h4>${escapeHtml(title)}</h4>
            <p class="patient-master-muted">${locked ? 'Signerad och låst.' : config.subtitle}</p>
          </div>
          ${
            locked
              ? chipHtml('Låst', 'violet')
              : `<button type="submit" class="customers-utility-button patient-master-tp-save">Spara journal</button>`
          }
        </header>
        ${sectionsHtml}
      </article>
    `;
  }

  function readForm(root) {
    if (!root) return {};
    const next = {};
    MULTI_FIELD_KEYS.forEach((key) => {
      next[key] = [];
    });
    root.querySelectorAll('[data-prp-field]').forEach((el) => {
      const key = el.dataset.prpField;
      if (!key) return;
      if (el.dataset.prpMulti === 'true') {
        if (el.checked) next[key].push(el.value);
        return;
      }
      if (el.tagName === 'SELECT') {
        const raw = String(el.value || '');
        if (el.dataset.prpTristate === 'true' || TRISTATE_FIELD_KEYS.has(key)) {
          if (raw === 'true') next[key] = true;
          else if (raw === 'false') next[key] = false;
          else next[key] = null;
          return;
        }
        next[key] = raw;
        return;
      }
      next[key] = String(el.value || '').trim();
    });
    return next;
  }

  function buildPrpForm(formVariant, schema) {
    const sections = asArray(schema.sections).map((section) => ({
      title: section.title,
      fields: asArray(section.fields).map((field) => ({ ...field })),
    }));
    sections.forEach((section) => section.fields.forEach(registerField));

    return Object.freeze({
      formVariant,
      meridiqQuestionaryId: schema.meridiqQuestionaryId,
      title: schema.title || 'PRP behandlingsjournal',
      subtitle: schema.subtitle || `Meridiq mall ${schema.meridiqQuestionaryId}`,
      sections,
      render: (entry, options) =>
        render(
          {
            formVariant,
            title: schema.title,
            subtitle: schema.subtitle || `Meridiq mall ${schema.meridiqQuestionaryId}`,
            sections,
          },
          entry,
          options
        ),
      defaultFields() {
        return { ...(schema.emptyDefaults || {}) };
      },
    });
  }

  const registry = window.ArcanaJournalPrpSchemaRegistry || {};
  const forms = {};
  Object.entries(registry).forEach(([formVariant, schema]) => {
    forms[formVariant] = buildPrpForm(formVariant, schema);
  });

  function resolveFormVariant(entry) {
    const variant = String(entry?.formVariant || '').trim();
    if (variant && forms[variant]) return variant;
    return forms.prp_skin ? 'prp_skin' : Object.keys(forms)[0] || 'prp_skin';
  }

  window.ArcanaJournalPrpForms = Object.freeze(forms);
  window.ArcanaJournalPrpForm = Object.freeze({
    forms,
    resolveForm(entry) {
      return forms[resolveFormVariant(entry)] || forms.prp_skin || null;
    },
    render(entry, options) {
      const form = this.resolveForm(entry);
      return form ? form.render(entry, options) : '';
    },
    readForm,
    defaultFields(formVariant = 'prp_skin') {
      return forms[formVariant]?.defaultFields?.() || forms.prp_skin?.defaultFields?.() || {};
    },
    resolveFormVariant,
  });
})();
